"use client";

import Link from "next/link";
import { useCallback, useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from "react";
import type { BusinessDashboard, BusinessExperiment, BusinessPublication, PublicationOutcome } from "@/lib/business-analytics/model";
import { useStudio } from "./StudioContext";
import { IconPlus, IconPlug } from "./icons";
import { BusinessEmpty, BusinessField, BusinessModal, CopyButton, businessError, businessRequest, formatBusinessMoney, moneyToMinor } from "./business-ui";
import "./business-results.css";

type Tab = "overview" | "content" | "revenue" | "links" | "experiments" | "settings";
type Dialog = "publication" | "link" | "cost" | "event" | "experiment" | null;
type Translate = (fr: string, en: string) => string;
type ImportPreview = { valid: boolean; rows: Array<Record<string, unknown>>; errors: Array<{ row?: number; message: string }>; imported?: number; skipped?: number };
const TABS: Array<[Tab, string, string]> = [["overview", "Synthèse", "Overview"], ["content", "Contenus", "Content"], ["revenue", "Ventes & coûts", "Sales & costs"], ["links", "Liens", "Links"], ["experiments", "Expériences", "Experiments"], ["settings", "Réglages", "Settings"]];
const currencyOptions = ["EUR", "USD", "GBP", "CAD", "AUD", "CHF", "JPY"];
const localInputDate = (date = new Date()) => new Date(date.getTime() - date.getTimezoneOffset() * 60_000).toISOString().slice(0, 16);
const percent = (value: number | null | undefined) => value == null ? "—" : `${Math.round(value)} %`;
const number = (value: number | null | undefined, en: boolean) => value == null ? "—" : value.toLocaleString(en ? "en-GB" : "fr-FR");
const dateLabel = (value: string | null | undefined, en: boolean) => value ? new Date(value).toLocaleDateString(en ? "en-GB" : "fr-FR", { day: "numeric", month: "short" }) : "—";

export function BusinessResultsView() {
  const { english: en, user, posts, channels } = useStudio();
  const tr: Translate = (fr, english) => en ? english : fr;
  const requestRef = useRef(0);
  const [data, setData] = useState<BusinessDashboard | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [days, setDays] = useState(30);
  const [horizon, setHorizon] = useState(30);
  const [currency, setCurrency] = useState("EUR");
  const [tab, setTab] = useState<Tab>("overview");
  const [basis, setBasis] = useState<"cash" | "content">("cash");
  const [dialog, setDialog] = useState<Dialog>(null);
  const [editingPublication, setEditingPublication] = useState<BusinessPublication | null>(null);
  const [editingExperiment, setEditingExperiment] = useState<BusinessExperiment | null>(null);
  const [search, setSearch] = useState("");
  const [origin, setOrigin] = useState("");
  const [deleteTarget, setDeleteTarget] = useState<{ kind: "links" | "costs" | "experiments" | "publications"; id: string; title: string } | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [rankBy, setRankBy] = useState<"format" | "hook" | "cta">("format");

  const load = useCallback(async (signal?: AbortSignal) => {
    const request = ++requestRef.current;
    const current = () => request === requestRef.current && !signal?.aborted;
    setRefreshing(true);
    try { const next = await businessRequest<BusinessDashboard>(`/dashboard?days=${days}&horizon=${horizon}&currency=${encodeURIComponent(currency)}`, undefined, "GET"); if (current()) { setData(next); setError(""); } }
    catch (failure) { if (current()) setError(businessError(failure, en)); }
    finally { if (current()) { setLoading(false); setRefreshing(false); } }
  }, [days, horizon, currency, en]);
  useEffect(() => { setData(null); setLoading(true); setDialog(null); setEditingPublication(null); setEditingExperiment(null); if (!user?.projectId) return; const controller = new AbortController(); void load(controller.signal); return () => { requestRef.current++; controller.abort(); }; }, [load, user?.projectId]);
  useEffect(() => { setOrigin(window.location.origin); const requested = new URLSearchParams(window.location.search).get("tab"); if (TABS.some(([key]) => key === requested)) setTab(requested as Tab); }, []);
  const changeTab = (next: Tab) => { setTab(next); window.history.replaceState(null, "", `/app/analytics${next === "overview" ? "" : `?tab=${next}`}`); };
  const money = (amount: number | null | undefined) => formatBusinessMoney(amount, data?.currency || currency, en);
  const afterSave = async () => { setDialog(null); setEditingPublication(null); setEditingExperiment(null); setNotice(tr("Enregistré. Les résultats ont été actualisés.", "Saved. Results have been refreshed.")); await load(); };
  const outcomes = data?.publicationOutcomes.filter(item => `${item.title} ${item.hook || ""} ${item.format}`.toLowerCase().includes(search.toLowerCase())) || [];
  const hasSource = Boolean(data?.capabilities.providerConnected || data?.transactions.length);
  const currencies = Array.from(new Set([...currencyOptions, ...(data?.cash.currencies || [])]));

  async function remove() {
    if (!deleteTarget) return; setDeleting(true);
    try { await businessRequest(`/${deleteTarget.kind}/${encodeURIComponent(deleteTarget.id)}`, {}, "DELETE"); setDeleteTarget(null); await load(); }
    catch (failure) { setError(businessError(failure, en)); } finally { setDeleting(false); }
  }

  return <div className="ss-br ss-br-page">
    <header className="ss-br__header"><div><p className="ss-br__eyebrow">{tr("RÉSULTATS BUSINESS", "BUSINESS RESULTS")}</p><h1>{tr("Du contenu aux clients.", "From content to customers.")}</h1><p className="ss-br__subtitle">{tr("Ce que tes contenus ont rapporté, ce qui est mesuré et ce qu'il reste à apprendre.", "What your content earned, what is measured and what there is still to learn.")}</p></div><div className="ss-br__actions"><Link href="/app/business-connections" className="ss-br__button lg lg--lens lg-press"><IconPlug size={15} />{tr("Connexions", "Connections")}</Link><button className="ss-br__primary" onClick={() => setDialog("publication")} disabled={!data}><IconPlus size={15} />{tr("Suivre un contenu", "Track content")}</button></div></header>
    <div className="ss-br__toolbar lg lg--flat"><div className="ss-br__tabs" role="tablist" aria-label={tr("Résultats business", "Business results")}>{TABS.map(([key, fr, eng]) => <button type="button" role="tab" id={`business-tab-${key}`} aria-controls={`business-panel-${key}`} aria-selected={tab === key} key={key} onClick={() => changeTab(key)}>{tr(fr, eng)}</button>)}</div><div className="ss-br__filters"><select aria-label={tr("Période", "Period")} value={days} onChange={event => setDays(Number(event.target.value))}>{[7, 30, 90, 365].map(value => <option key={value} value={value}>{value} {tr("jours", "days")}</option>)}</select><select aria-label={tr("Devise sans conversion", "Currency without conversion")} value={currency} onChange={event => setCurrency(event.target.value)}>{currencies.map(value => <option key={value}>{value}</option>)}</select><button className="ss-br__icon-button" onClick={() => void load()} disabled={refreshing} aria-label={tr("Actualiser", "Refresh")} title={tr("Actualiser les résultats", "Refresh results")}>↻</button></div></div>
    {error && <div className="ss-br__notice is-error" role="alert"><span>{error}</span><button className="ss-br__button" onClick={() => void load()}>{tr("Réessayer", "Retry")}</button></div>}
    {notice && <div className="ss-br__notice is-success" role="status"><span>{notice}</span><button className="ss-br__icon-button" onClick={() => setNotice("")} aria-label={tr("Fermer", "Dismiss")}>×</button></div>}
    {loading ? <div className="ss-br__metric-grid" aria-busy="true" aria-label={tr("Chargement des résultats", "Loading results")}>{[1, 2, 3, 4].map(key => <div className="ss-br__metric" key={key}><span className="ss-br__metric-label">{tr("Chargement…", "Loading…")}</span><b className="ss-br__metric-value">—</b></div>)}</div> : !data ? <section className="ss-br__panel"><BusinessEmpty title={tr("Les résultats ne sont pas disponibles", "Results are unavailable")} body={tr("Tes données n'ont pas pu être chargées. Réessaie ou vérifie la configuration des connexions.", "Your data could not be loaded. Try again or check connection setup.")} action={<Link className="ss-br__button lg" href="/app/business-connections">{tr("Vérifier les connexions", "Check connections")}</Link>} /></section> : <div role="tabpanel" id={`business-panel-${tab}`} aria-labelledby={`business-tab-${tab}`}>
      {!hasSource && tab === "overview" && <div className="ss-br__notice lg lg--flat"><span>{tr("Les paiements de ton activité apparaîtront dès qu'une source sera connectée ou un historique importé.", "Your business payments will appear once a source is connected or history is imported.")}</span><Link href="/app/business-connections">{tr("Connecter les revenus", "Connect revenue")}</Link></div>}
      {data.coverage.truncated.length > 0 && <div className="ss-br__notice is-error" role="status">{tr("La collecte est partielle. Les résultats affichés ne couvrent pas tout l'historique.", "Collection is partial. These results do not cover the full history.")}</div>}
      {tab === "overview" && <>
        <div className="ss-br__actions" style={{ marginBottom: 18 }}><div className="ss-br__tabs lg lg--lens" role="tablist" aria-label={tr("Base de calcul", "Calculation basis")}><button role="tab" aria-selected={basis === "cash"} onClick={() => setBasis("cash")}>{tr("Encaissements de la période", "Cash in this period")}</button><button role="tab" aria-selected={basis === "content"} onClick={() => setBasis("content")}>{tr("Contenus à horizon égal", "Content at equal maturity")}</button></div>{basis === "content" && <HorizonSelect value={horizon} onChange={setHorizon} tr={tr} />}</div>
        <div className="ss-br__metric-grid">{basis === "cash" ? <><Metric label={tr("Encaissements", "Collected revenue")} value={money(data.cash.grossMinor)} detail={`${dateLabel(data.period.from, en)} – ${dateLabel(data.period.to, en)} · ${currency}`} /><Metric label={tr("Revenu net de TVA et remboursements", "Revenue after tax and refunds")} value={money(data.cash.netRevenueMinor)} detail={tr("Frais et coûts à déduire séparément", "Fees and costs deducted separately")} /><Metric label={tr("Paiements", "Payments")} value={hasSource ? number(data.cash.sales, en) : "—"} detail={tr("Transactions payées, renouvellements inclus", "Paid transactions, including renewals")} /><Metric label={tr("Ventes rattachées", "Sales with a known source")} value={percent(data.coverage.attributedSalesPercent)} detail={tr("Une association observée, pas une preuve causale", "An observed association, not causal proof")} /></> : <><Metric label={tr(`Revenu par post à J${horizon}`, `Revenue per post at D${horizon}`)} value={money(data.content.revenuePerPostMinor)} detail={`${data.content.eligiblePublications} ${tr("publications éligibles", "eligible publications")}`} /><Metric label={tr("Contribution par post", "Contribution per post")} value={money(data.content.contributionPerPostMinor)} detail={data.coverage.costsComplete ? tr("Après les coûts renseignés", "After recorded costs") : tr("Renseigne et confirme l'ensemble des coûts", "Record and confirm complete costs")} /><Metric label={tr("Acheteurs rattachés", "Linked buyers")} value={number(data.content.buyers, en)} detail={tr("Dans la fenêtre des contenus éligibles", "Within the eligible content window")} /><Metric label={tr("Contenus en maturation", "Content still maturing")} value={number(data.content.immaturePublications, en)} detail={tr("Exclus de la comparaison à horizon égal", "Excluded from equal-horizon comparisons")} /></>}</div>
        {basis === "content" && <p className="ss-br__caption">{tr("Cohorte publiée du", "Cohort published from")} {dateLabel(data.cohortPeriod.from, en)} {tr("au", "to")} {dateLabel(data.cohortPeriod.to, en)}. {tr("Chaque publication est observée sur la même durée. Les suivis incomplets sont exclus.", "Each publication is observed for the same duration. Incomplete tracking is excluded.")}</p>}
        <div className="ss-br__grid"><section className="ss-br__panel"><PanelTitle title={tr("Le revenu au fil du temps", "Revenue over time")} detail={tr("Encaissements calendaires et remboursements • aucune conversion de devise", "Calendar receipts and refunds • no currency conversion")} />{data.cash.grossMinor == null ? <BusinessEmpty title={tr("Commence par une source de revenus", "Start with a revenue source")} body={tr("La courbe se dessinera avec les transactions réellement reçues.", "The chart will use transactions actually received.")} action={<Link href="/app/business-connections" className="ss-br__button lg lg--lens">{tr("Connecter une source", "Connect a source")}</Link>} /> : <RevenueChart data={data} en={en} />}</section><Coverage data={data} tr={tr} en={en} /></div>
        <section className="ss-br__panel"><PanelTitle title={tr("Du clic au premier client", "From a click to a customer")} detail={tr("Étapes mesurées sur la période. Les événements déclarés restent identifiés comme tels.", "Measured steps in this period. Manually recorded events retain their source.")} action={<button className="ss-br__button lg lg--lens" onClick={() => setDialog("event")}>{tr("Ajouter un signal", "Add a signal")}</button>} /><div className="ss-br__funnel">{data.funnel.map(step => <div className="ss-br__funnel-step" key={step.key}><span>{({ visits: tr("Visites", "Visits"), signups: tr("Inscriptions", "Signups"), activations: tr("Activations", "Activations"), buyers: tr("Acheteurs", "Buyers") })[step.key]}</span><b>{step.measured ? number(step.count, en) : "—"}</b><small>{step.measured ? step.rate == null ? tr("Point de départ", "Starting point") : `${percent(step.rate)} ${step.key === "buyers" ? data.funnel.find(item => item.key === "activations")?.measured ? tr("des inscrits activés", "of activated signups") : tr("des visiteurs inscrits", "of signed-up visitors") : step.key === "activations" ? tr("des visiteurs inscrits", "of signed-up visitors") : tr("des visiteurs suivis", "of tracked visitors")}` : tr("Non mesuré", "Not measured")}</small></div>)}</div></section>
        {data.customerCohorts.length > 0 && <section className="ss-br__panel"><PanelTitle title={tr("Ce que deviennent les clients", "What happens after the first purchase")} detail={tr("Cohortes de nouveaux clients dont l’horizon est terminé. Chaque ligne conserve son nombre de clients.", "New-customer cohorts whose observation horizon is complete. Each row retains its customer count.")} /><div className="ss-br__table-scroll"><table><thead><tr><th>{tr("Horizon", "Horizon")}</th><th>{tr("Clients", "Customers")}</th><th>{tr("Revenu mesuré", "Measured revenue")}</th><th>{tr("Revenu par client", "Revenue per customer")}</th><th>{tr("Clients ayant renouvelé", "Customers who renewed")}</th></tr></thead><tbody>{data.customerCohorts.map(row => <tr key={row.horizonDays}><td>{tr(`J${row.horizonDays}`, `D${row.horizonDays}`)}</td><td>{row.customers}</td><td>{money(row.revenueMinor)}</td><td>{money(row.revenuePerCustomerMinor)}</td><td>{row.renewalCustomers}</td></tr>)}</tbody></table></div></section>}
        <section className="ss-br__panel"><PanelTitle title={tr("La prochaine étape", "Your next step")} detail={tr("Des décisions à partir de la couverture réelle de tes données.", "Decisions based on your actual data coverage.")} /><div className="ss-br__panel-body"><ol className="ss-br__progress-list"><li><span>{data.capabilities.providerConnected ? "✓" : "1"}</span><div><strong>{tr("Vérifier une source de revenus", "Verify a revenue source")}</strong><p>{data.capabilities.providerConnected ? tr("Une connexion est vérifiée. Contrôle aussi la fraîcheur et les événements reçus.", "A connection is verified. Also check freshness and received events.") : tr("Connecte ton fournisseur de paiement pour importer les transactions de ton activité.", "Connect your payment provider to import business transactions.")}</p><Link href="/app/business-connections" className="ss-br__text-link">{tr("Voir les connexions", "View connections")}</Link></div></li><li><span>{data.capabilities.trackingObserved ? "✓" : "2"}</span><div><strong>{tr("Relier une visite à un client", "Link a visit to a customer")}</strong><p>{data.capabilities.trackingObserved ? tr("Des événements de suivi ont été reçus. Les ventes sans correspondance restent inconnues.", "Tracking events have been received. Unmatched sales remain unknown.") : tr("Installe le suivi, puis vérifie une inscription issue d'un lien dédié.", "Install tracking, then verify a signup from a dedicated link.")}</p><button className="ss-br__icon-button" onClick={() => changeTab("settings")}>{tr("Configurer le suivi", "Set up tracking")} →</button></div></li><li><span>3</span><div><strong>{tr("Comparer des contenus comparables", "Compare comparable content")}</strong><p>{tr("Attends leur maturité et vérifie les volumes avant de tirer une conclusion. Un test organique reste observationnel.", "Wait for maturity and check sample sizes before drawing conclusions. An organic content test remains observational.")}</p><button className="ss-br__icon-button" onClick={() => changeTab("experiments")}>{tr("Préparer une expérience", "Plan an experiment")} →</button></div></li></ol></div></section>
      </>}
      {tab === "content" && <>
        {data.publications.some(item => item.lifecycle === "planned") && <section className="ss-br__panel"><PanelTitle title={tr("Prêts avant publication", "Ready before publishing")} detail={tr("Crée le lien et vérifie le suivi avant de publier. Ces contenus sont exclus des résultats jusqu’à leur publication.", "Create the link and verify tracking before publishing. These items stay outside results until published.")} /><div className="ss-br__table-scroll"><table><thead><tr><th>{tr("Contenu prévu", "Planned content")}</th><th>{tr("Date prévue", "Planned date")}</th><th>{tr("Lien dédié", "Dedicated link")}</th><th>{tr("Publication", "Publishing")}</th></tr></thead><tbody>{data.publications.filter(item => item.lifecycle === "planned").map(item => <tr key={item.id}><td><strong>{item.title}</strong><small>{item.format}</small></td><td>{dateLabel(item.publishedAt, en)}</td><td>{data.links.some(link => link.active && link.publicationId === item.id) ? <span className="ss-br__pill is-good">{tr("Lien créé", "Link created")}</span> : <button className="ss-br__button lg" onClick={() => { setEditingPublication(item); setDialog("link"); }}>{tr("Créer le lien", "Create link")}</button>}</td><td><button className="ss-br__button lg" onClick={() => { setEditingPublication(item); setDialog("publication"); }}>{tr("Marquer publié", "Mark published")}</button></td></tr>)}</tbody></table></div></section>}
        <div className="ss-br__notice lg lg--flat"><span>{tr("Le revenu par post compare uniquement les publications matures avec un suivi complet.", "Revenue per post compares only mature publications with complete tracking.")}</span><HorizonSelect value={horizon} onChange={setHorizon} tr={tr} /></div>
        <section className="ss-br__panel"><PanelTitle title={tr("Résultats par publication", "Results by publication")} detail={`${data.content.eligiblePublications} ${tr("éligibles", "eligible")} · ${data.content.immaturePublications} ${tr("en maturation", "maturing")} · ${currency}`} action={<button className="ss-br__button lg lg--lens" onClick={() => setDialog("publication")}><IconPlus size={13} />{tr("Ajouter", "Add")}</button>} /><div className="ss-br__search"><input aria-label={tr("Rechercher un contenu", "Search content")} placeholder={tr("Rechercher une accroche, un format…", "Search a hook, format…")} value={search} onChange={event => setSearch(event.target.value)} /></div>{!outcomes.length ? <BusinessEmpty title={tr("Chaque contenu mérite son suivi", "Give every content piece its own tracking")} body={tr("Ajoute une publication du calendrier ou son URL pour lui associer un lien, un format et des coûts.", "Add a calendar publication or its URL to associate a link, format and costs.")} action={<button className="ss-br__primary" onClick={() => setDialog("publication")}>{tr("Suivre un contenu", "Track content")}</button>} /> : <div className="ss-br__table-scroll"><table><thead><tr>{[tr("Publication", "Publication"), tr("Vues", "Views"), tr("Visites", "Visits"), tr("Acheteurs", "Buyers"), tr("Revenu", "Revenue"), tr("Contribution", "Contribution"), tr("Suivi", "Tracking"), tr("Actions", "Actions")].map(label => <th key={label}>{label}</th>)}</tr></thead><tbody>{outcomes.map(item => <tr key={item.id}><td>{item.url ? <a className="ss-br__table-title ss-br__text-link" href={item.url} target="_blank" rel="noreferrer">{item.title}</a> : <span className="ss-br__table-title">{item.title}</span>}<small>{dateLabel(item.publishedAt, en)} · {item.format} · {tr(`J${item.ageDays}`, `D${item.ageDays}`)}</small></td><td>{number(item.horizonViews, en)}<small>{tr(`à J${horizon}`, `at D${horizon}`)}</small></td><td>{number(item.visits, en)}</td><td>{number(item.buyers, en)}</td><td>{money(item.revenueMinor)}<small>{item.renewalRevenueMinor != null && item.renewalRevenueMinor > 0 ? `${money(item.renewalRevenueMinor)} ${tr("renouvellements", "renewals")}` : tr("Source liée au contenu", "Content-linked source")}</small></td><td>{money(item.contributionMinor)}</td><td><span className={`ss-br__pill ${item.eligible ? "is-good" : "is-warn"}`}>{outcomeStatus(item, horizon, tr)}</span></td><td><button className="ss-br__icon-button" onClick={() => { setEditingPublication(data.publications.find(pub => pub.id === item.id) || null); setDialog("publication"); }}>{tr("Modifier", "Edit")}</button></td></tr>)}</tbody></table></div>}</section>
        <section className="ss-br__panel"><PanelTitle title={tr("Ce qui mérite d'être exploré", "What deserves a closer look")} detail={tr("Comparaisons descriptives des publications éligibles. Les petits volumes restent visibles.", "Descriptive comparisons of eligible publications. Small sample sizes stay visible.")} action={<select aria-label={tr("Regrouper par", "Group by")} className="ss-br__button" value={rankBy} onChange={event => setRankBy(event.target.value as typeof rankBy)}><option value="format">{tr("Format", "Format")}</option><option value="hook">{tr("Accroche", "Hook")}</option><option value="cta">CTA</option></select>} /><Rankings outcomes={data.publicationOutcomes} group={rankBy} currency={currency} en={en} /></section>
      </>}
      {tab === "revenue" && <>
        <div className="ss-br__metric-grid"><Metric label={tr("Encaissements", "Collected revenue")} value={money(data.cash.grossMinor)} detail={currency} /><Metric label={tr("Remboursements", "Refunds")} value={money(data.cash.refundsMinor)} detail={tr("À leur date de remboursement", "On their refund date")} /><Metric label={tr("TVA connue", "Known tax")} value={money(data.cash.taxMinor)} detail={`${percent(data.coverage.knownTaxesPercent)} ${tr("de couverture", "coverage")}`} /><Metric label={tr("Revenu net", "Net revenue")} value={money(data.cash.netRevenueMinor)} detail={tr("Après TVA et remboursements", "After tax and refunds")} /></div>
        <SalesLedger data={data} en={en} />
        <section className="ss-br__panel"><PanelTitle title={tr("Coûts des contenus", "Content costs")} detail={tr("Les montants renseignés servent à calculer la contribution, sans les confondre avec le bénéfice total du business.", "Recorded amounts help calculate contribution, not total business profit.")} action={<button className="ss-br__button lg lg--lens" onClick={() => setDialog("cost")}><IconPlus size={13} />{tr("Ajouter un coût", "Add cost")}</button>} />{!data.costs.length ? <BusinessEmpty title={tr("Le revenu ne raconte pas tout", "Revenue is part of the picture")} body={tr("Ajoute le temps de production valorisé, la création, les outils ou les dépenses publicitaires de chaque contenu.", "Add valued production time, creative work, tools or advertising costs for each content piece.")} action={<button className="ss-br__button lg" onClick={() => setDialog("cost")}>{tr("Renseigner un coût", "Record a cost")}</button>} /> : <div className="ss-br__table-scroll"><table><thead><tr><th>{tr("Dépense", "Expense")}</th><th>{tr("Publication", "Publication")}</th><th>{tr("Date", "Date")}</th><th>{tr("Montant", "Amount")}</th><th><span className="sr-only">{tr("Actions", "Actions")}</span></th></tr></thead><tbody>{data.costs.map(cost => <tr key={cost.id}><td><strong>{cost.name}</strong><small>{cost.category}</small></td><td>{data.publications.find(pub => pub.id === cost.publicationId)?.title || tr("Coût global", "Global cost")}</td><td>{dateLabel(cost.incurredAt, en)}</td><td>{formatBusinessMoney(cost.amountMinor, cost.currency, en)}</td><td><button className="ss-br__icon-button" aria-label={`${tr("Supprimer", "Delete")} ${cost.name}`} onClick={() => setDeleteTarget({ kind: "costs", id: cost.id, title: cost.name })}>×</button></td></tr>)}</tbody></table></div>}<div className="ss-br__panel-body"><p className="ss-br__caption">{data.coverage.costsComplete ? tr("Les coûts sont déclarés complets dans les réglages.", "Costs are marked complete in settings.") : tr("La contribution reste non calculée tant que les coûts ne sont pas déclarés complets.", "Contribution remains uncalculated until costs are marked complete.")} <button className="ss-br__icon-button" onClick={() => changeTab("settings")}>{tr("Vérifier", "Review")} →</button></p></div></section>
      </>}
      {tab === "links" && <>
        <section className="ss-br__panel"><PanelTitle title={tr("Un lien, une provenance", "One link, a traceable origin")} detail={tr("Un lien dédié identifie le contenu sélectionné. Une bio commune ne révèle pas automatiquement le dernier post vu.", "A dedicated link identifies the selected content. A shared bio does not reveal the last post viewed.")} action={<button className="ss-br__button lg lg--lens" onClick={() => setDialog("link")}><IconPlus size={13} />{tr("Créer un lien", "Create link")}</button>} />{!data.links.length ? <BusinessEmpty title={tr("Ton premier lien traçable", "Your first trackable link")} body={tr("Choisis une destination : page produit, inscription, ressource ou essai. Relie-la à une publication pour suivre la suite du parcours.", "Choose a destination: product page, signup, resource or trial. Associate a publication to track the rest of the journey.")} action={<button className="ss-br__primary" onClick={() => setDialog("link")}>{tr("Créer un lien", "Create link")}</button>} /> : <div className="ss-br__table-scroll"><table><thead><tr><th>{tr("Lien", "Link")}</th><th>{tr("Contenu", "Content")}</th><th>{tr("Statut", "Status")}</th><th>{tr("Partager", "Share")}</th></tr></thead><tbody>{data.links.map(link => <tr key={link.id}><td><strong>{link.label}</strong><small>{link.destinationUrl}</small><small>{origin}/go/{link.slug}</small></td><td><span className="ss-br__table-title">{data.publications.find(pub => pub.id === link.publicationId)?.title || link.campaign || tr("Sans publication", "No publication")}</span></td><td><span className={`ss-br__pill ${link.active ? "is-good" : ""}`}>{link.active ? tr("Actif", "Active") : tr("Désactivé", "Disabled")}</span></td><td><div className="ss-br__actions" style={{ justifyContent: "flex-end" }}>{link.active && <CopyButton value={`${origin}/go/${link.slug}`} english={en} />}{link.active && <button className="ss-br__icon-button" onClick={() => setDeleteTarget({ kind: "links", id: link.id, title: link.label })}>{tr("Désactiver", "Disable")}</button>}</div></td></tr>)}</tbody></table></div>}</section>
        <section className="ss-br__panel"><PanelTitle title={tr("Ta page bio", "Your bio page")} detail={tr("Une porte d'entrée visuelle vers les contenus suivis de ce projet.", "A visual entry point to tracked content in this project.")} /><div className="ss-br__panel-body">{data.settings.bioEnabled && data.settings.bioSlug ? <><a className="ss-br__text-link" target="_blank" rel="noreferrer" href={`/b/${encodeURIComponent(data.settings.bioSlug)}`}>{origin}/b/{data.settings.bioSlug}</a><div className="ss-br__actions" style={{ marginTop: 14 }}><CopyButton value={`${origin}/b/${data.settings.bioSlug}`} english={en} /></div></> : <p className="ss-br__caption">{tr("Définis une adresse et active la bio dans les réglages pour partager tes liens.", "Choose an address and enable the bio in settings to share your links.")}</p>}<button className="ss-br__icon-button" onClick={() => changeTab("settings")}>{tr("Configurer la bio", "Configure bio")} →</button></div></section>
      </>}
      {tab === "experiments" && <>
        <section className="ss-br__panel"><PanelTitle title={tr("Le point de la semaine", "Your weekly review")} detail={tr("Un rapport des mesures disponibles, avec trois pistes d’expérience à préparer avec ton agent.", "A report of available measurements, with three experiment directions to prepare with your agent.")} /><div className="ss-br__panel-body"><div className="ss-br__actions"><a className="ss-br__button lg lg--lens" href={`/api/business/report?days=7&currency=${encodeURIComponent(currency)}`} download>{tr("Télécharger le rapport (.md)", "Download report (.md)")}</a><CopyButton english={en} label={tr("Copier le brief pour l’agent", "Copy agent brief")} value={tr("Appelle get_business_results pour mon projet actif. Analyse couverture, horizon et volumes ; distingue mesure, association et hypothèse. Propose trois brouillons originaux de contenus et trois expériences mesurables. Pour chaque contenu, propose format, accroche, CTA, coût prévu et lien dédié à créer avant publication. Ne publie rien sans ma demande.", "Call get_business_results for my active project. Analyze coverage, horizon and sample sizes; distinguish measurement, association and hypothesis. Propose three original content drafts and three measurable experiments. For each piece, suggest format, hook, CTA, expected cost and a dedicated link to create before publishing. Do not publish anything without my request.")} /><Link href="/app/mcp" className="ss-br__text-link">{tr("Connecter mon agent", "Connect my agent")} →</Link></div></div></section>

        <section className="ss-br__panel"><PanelTitle title={tr("Une hypothèse, un prochain essai", "One hypothesis, a next experiment")} detail={tr("Les expériences organiques sont observationnelles : horaires, audience et diffusion peuvent varier.", "Organic experiments are observational: timing, audience and distribution may differ.")} action={<button className="ss-br__button lg lg--lens" onClick={() => setDialog("experiment")}><IconPlus size={13} />{tr("Nouvelle expérience", "New experiment")}</button>} />{!data.experiments.length ? <BusinessEmpty title={tr("Donne un objectif au prochain contenu", "Give your next content piece a goal")} body={tr("Choisis une seule différence à explorer : accroche, format ou appel à l'action. Note le résultat attendu avant de publier.", "Choose one difference to explore: hook, format or call to action. Record your expected result before publishing.")} action={<button className="ss-br__primary" onClick={() => setDialog("experiment")}>{tr("Préparer un essai", "Plan an experiment")}</button>} /> : data.experiments.map(experiment => <article className="ss-br__experiment" key={experiment.id}><div className="ss-br__connection-head"><h3>{experiment.name}</h3><span className="ss-br__pill">{experiment.status === "planned" ? tr("Préparée", "Planned") : experiment.status === "running" ? tr("En cours", "Running") : tr("Terminée", "Completed")}</span></div><p>{experiment.hypothesis}</p><small className="ss-br__caption">{experiment.metric} · {experiment.publicationIds.length} {tr("publications", "publications")} · {tr("Observationnel", "Observational")}</small><div className="ss-br__actions" style={{ marginTop: 12 }}><button className="ss-br__button lg" onClick={() => { setEditingExperiment(experiment); setDialog("experiment"); }}>{tr("Modifier", "Edit")}</button><button className="ss-br__icon-button" onClick={() => setDeleteTarget({ kind: "experiments", id: experiment.id, title: experiment.name })}>{tr("Supprimer", "Delete")}</button></div></article>)}</section>
        <BusinessSimulator currency={currency} english={en} />
      </>}
      {tab === "settings" && <BusinessSettingsPanel data={data} english={en} origin={origin} reload={load} />}
    </div>}
    {data && <footer className="ss-br__status-line"><span>{tr("Projet actif", "Current project")} · {currency} · {tr("Devises séparées, sans conversion", "Currencies kept separate, no conversion")}</span><span>{tr("Actualisé", "Updated")} {new Date(data.generatedAt).toLocaleTimeString(en ? "en-GB" : "fr-FR", { hour: "2-digit", minute: "2-digit" })} · {tr("Attribution observée ≠ causalité", "Observed attribution ≠ causality")}</span></footer>}
    {dialog && data && <BusinessEntryForm publication={editingPublication || undefined} experiment={editingExperiment || undefined} kind={dialog} data={data} english={en} posts={posts} channels={channels} onClose={() => { setDialog(null); setEditingPublication(null); setEditingExperiment(null); }} onSaved={afterSave} />}
    {deleteTarget && <BusinessModal title={tr("Confirmer cette action", "Confirm this action")} onClose={() => setDeleteTarget(null)} english={en}><div className="ss-br__modal-content"><p>{deleteTarget.kind === "links" ? tr(`Désactiver le lien « ${deleteTarget.title} » ? Les prochains clics ne seront plus redirigés.`, `Disable “${deleteTarget.title}”? Future clicks will no longer redirect.`) : tr(`Supprimer « ${deleteTarget.title} » ? Les résultats seront recalculés.`, `Delete “${deleteTarget.title}”? Results will be recalculated.`)}</p><div className="ss-br__modal-footer"><button className="ss-br__button" onClick={() => setDeleteTarget(null)}>{tr("Annuler", "Cancel")}</button><button className="ss-br__primary" disabled={deleting} onClick={() => void remove()}>{deleting ? tr("En cours…", "Working…") : tr("Confirmer", "Confirm")}</button></div></div></BusinessModal>}
  </div>;
}

function Metric({ label, value, detail }: { label: string; value: string; detail: string }) { return <div className="ss-br__metric"><span className="ss-br__metric-label">{label}</span><strong className="ss-br__metric-value">{value}</strong><small>{detail}</small></div>; }
function PanelTitle({ title, detail, action }: { title: string; detail?: string; action?: ReactNode }) { return <div className="ss-br__panel-head"><div><h2>{title}</h2>{detail && <p>{detail}</p>}</div>{action}</div>; }
function HorizonSelect({ value, onChange, tr }: { value: number; onChange: (value: number) => void; tr: Translate }) { return <select className="ss-br__button lg lg--lens" value={value} onChange={event => onChange(Number(event.target.value))} aria-label={tr("Horizon de maturité", "Maturity horizon")}>{[7, 14, 30, 60, 90].map(day => <option key={day} value={day}>{tr(`Horizon J${day}`, `D${day} horizon`)}</option>)}</select>; }
function outcomeStatus(item: PublicationOutcome, horizon: number, tr: Translate) { if (item.eligible) return tr(`Mesuré à J${horizon}`, `Measured at D${horizon}`); return item.exclusionReason === "immature" ? tr("En maturation", "Maturing") : item.exclusionReason === "history_incomplete" ? tr("Historique partiel", "Partial history") : item.exclusionReason === "tracking_incomplete" ? tr("Suivi incomplet", "Incomplete tracking") : tr("Suivi manquant", "Missing tracking"); }

function Coverage({ data, tr, en }: { data: BusinessDashboard; tr: Translate; en: boolean }) {
  return <section className="ss-br__panel"><PanelTitle title={tr("Ce que l'on sait", "What we know")} detail={tr("La couverture fait partie du résultat.", "Coverage is part of the result.")} /><div className="ss-br__panel-body"><div className="ss-br__coverage-value">{percent(data.coverage.attributedSalesPercent)}</div><span className="ss-br__caption">{tr("des ventes reliées à un contenu ou une campagne", "of sales linked to content or a campaign")}</span><div className="ss-br__meter"><span style={{ width: `${Math.min(100, Math.max(0, data.coverage.attributedSalesPercent || 0))}%` }} /></div><div className="ss-br__key-value"><span>{tr("Publications éligibles", "Eligible publications")}</span><b>{data.content.eligiblePublications} / {data.content.totalPublications}</b></div><div className="ss-br__key-value"><span>{tr("Vues mesurées", "Measured views")}</span><b>{percent(data.coverage.measuredViewsPercent)}</b></div><div className="ss-br__key-value"><span>{tr("Dernière collecte", "Last collection")}</span><b>{dateLabel(data.coverage.lastSyncedAt, en)}</b></div><p className="ss-br__caption">{tr("Le reste conserve une origine inconnue. Aucune vente n'est répartie au prorata des vues.", "The rest keeps an unknown origin. No sales are distributed in proportion to views.")}</p></div></section>;
}

function RevenueChart({ data, en }: { data: BusinessDashboard; en: boolean }) {
  const items = data.timeline;
  const maximum = Math.max(1, ...items.map(item => Math.max(item.grossMinor, item.refundsMinor)));
  const points = (key: "grossMinor" | "refundsMinor") => items.map((item, index) => `${items.length > 1 ? index / (items.length - 1) * 600 : 300},${155 - item[key] / maximum * 135}`).join(" ");
  return <><div className="ss-br__chart"><svg viewBox="0 0 600 175" preserveAspectRatio="none" role="img" aria-label={en ? "Collected revenue and refunds by day" : "Encaissements et remboursements par jour"}><defs><linearGradient id="business-chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="currentColor" stopOpacity=".07" /><stop offset="100%" stopColor="currentColor" stopOpacity="0" /></linearGradient></defs>{[20, 65, 110, 155].map(y => <line x1="0" y1={y} x2="600" y2={y} key={y} stroke="var(--ss-line)" strokeDasharray="3 5" />)}{items.length > 0 && <><polygon points={`0,155 ${points("grossMinor")} 600,155`} fill="url(#business-chart-fill)" /><polyline points={points("grossMinor")} fill="none" stroke="currentColor" strokeWidth="2" vectorEffect="non-scaling-stroke" /><polyline points={points("refundsMinor")} fill="none" stroke="var(--ss-warn-fg)" strokeWidth="1.5" strokeDasharray="4 4" vectorEffect="non-scaling-stroke" />{items.map((item, index) => <circle key={item.date} cx={items.length > 1 ? index / (items.length - 1) * 600 : 300} cy={155 - item.grossMinor / maximum * 135} r="2" fill="currentColor"><title>{dateLabel(item.date, en)} : {formatBusinessMoney(item.grossMinor, data.currency, en)}</title></circle>)}</>}</svg></div><div className="ss-br__chart-labels"><span>{dateLabel(data.period.from, en)}</span><span>{en ? "Solid: collected · Dashed: refunds" : "Plein : encaissé · Pointillé : remboursé"}</span><span>{dateLabel(data.period.to, en)}</span></div></>;
}

function Rankings({ outcomes, group, currency, en }: { outcomes: PublicationOutcome[]; group: "format" | "hook" | "cta"; currency: string; en: boolean }) {
  const rows = useMemo(() => { const groups = new Map<string, { label: string; count: number; buyers: number; revenue: number; known: boolean }>(); for (const item of outcomes.filter(row => row.eligible)) { const label = item[group]?.trim() || (en ? "Unspecified" : "Non renseigné"); const row = groups.get(label) || { label, count: 0, buyers: 0, revenue: 0, known: true }; row.count++; row.buyers += item.buyers; if (item.revenueMinor == null) row.known = false; else row.revenue += item.revenueMinor; groups.set(label, row); } return Array.from(groups.values()).sort((a, b) => (b.known ? b.revenue / b.count : -1) - (a.known ? a.revenue / a.count : -1)); }, [outcomes, group, en]);
  if (!rows.length) return <BusinessEmpty title={en ? "Let your content mature" : "Laisse tes contenus arriver à maturité"} body={en ? "Group comparisons appear when publications have complete tracking for the selected horizon." : "Les comparaisons apparaissent quand les publications disposent d'un suivi complet sur l'horizon choisi."} />;
  return <div className="ss-br__table-scroll"><table><thead><tr><th>{en ? "Group" : "Groupe"}</th><th>{en ? "Publications" : "Publications"}</th><th>{en ? "Buyers" : "Acheteurs"}</th><th>{en ? "Revenue per post" : "Revenu par post"}</th><th>{en ? "Interpretation" : "Interprétation"}</th></tr></thead><tbody>{rows.map(row => <tr key={row.label}><td><span className="ss-br__table-title">{row.label}</span></td><td>{row.count}</td><td>{row.buyers}</td><td>{formatBusinessMoney(row.known ? row.revenue / row.count : null, currency, en)}</td><td><span className="ss-br__pill">{en ? "Observed sample" : "Échantillon observé"}</span></td></tr>)}</tbody></table></div>;
}

function SalesLedger({ data, en }: { data: BusinessDashboard; en: boolean }) {
  const [kind, setKind] = useState("all");
  const tr: Translate = (fr, english) => en ? english : fr;
  const within = (date: string, currency: string) => date >= data.period.from && date <= data.period.to && currency === data.currency;
  const rows = [...data.transactions.filter(item => within(item.occurredAt, item.currency)).map(item => ({ id: item.id, date: item.occurredAt, amount: item.amountMinor, currency: item.currency, title: item.productId || item.externalId, kind: item.kind, provider: item.provider, source: item.source, attribution: item.attributionModel, linked: Boolean(item.publicationId || item.campaign), status: item.status })), ...data.adjustments.filter(item => within(item.occurredAt, item.currency) && data.transactions.some(transaction => transaction.id === item.transactionId)).map(item => ({ id: item.id, date: item.occurredAt, amount: item.amountMinor * (item.kind === "reversal" ? 1 : -1), currency: item.currency, title: item.externalId, kind: item.kind, provider: item.provider, source: item.source, attribution: data.transactions.find(tx => tx.id === item.transactionId)?.attributionModel, linked: Boolean(data.transactions.find(tx => tx.id === item.transactionId)?.publicationId || data.transactions.find(tx => tx.id === item.transactionId)?.campaign), status: "paid" }))].filter(item => kind === "all" || item.kind === kind).sort((a, b) => b.date.localeCompare(a.date));
  const labels: Record<string, string> = { initial: tr("Premier achat", "Initial purchase"), renewal: tr("Renouvellement", "Renewal"), one_time: tr("Achat unique", "One-time purchase"), unknown: tr("Paiement", "Payment"), refund: tr("Remboursement", "Refund"), dispute: tr("Litige", "Dispute"), reversal: tr("Annulation du remboursement", "Refund reversal") };
  return <section className="ss-br__panel"><PanelTitle title={tr("Journal des ventes", "Sales ledger")} detail={tr("Transactions et remboursements dans la devise et la période sélectionnées.", "Transactions and refunds in the selected currency and period.")} action={<div className="ss-br__actions"><select className="ss-br__button" value={kind} onChange={event => setKind(event.target.value)} aria-label={tr("Type de transaction", "Transaction type")}><option value="all">{tr("Tout", "All")}</option>{Object.entries(labels).map(([key, value]) => <option value={key} key={key}>{value}</option>)}</select><a className="ss-br__button lg lg--lens" href="/api/business/export?kind=transactions" title={tr("Historique complet, toutes devises", "Full history, all currencies")} download>{tr("Ventes CSV", "Sales CSV")}</a><a className="ss-br__button lg lg--lens" href="/api/business/export?kind=adjustments" title={tr("Historique complet des ajustements, toutes devises", "Full adjustment history, all currencies")} download>{tr("Ajustements CSV", "Adjustments CSV")}</a></div>} />{!rows.length ? <BusinessEmpty title={tr("Aucune transaction dans cette période", "No transactions in this period")} body={tr("Les paiements reçus ou importés apparaîtront ici avec leur source et leur état.", "Received or imported payments will appear here with their source and status.")} /> : <div className="ss-br__table-scroll"><table><thead><tr><th>{tr("Transaction", "Transaction")}</th><th>{tr("Date", "Date")}</th><th>{tr("Source", "Source")}</th><th>{tr("Origine", "Origin")}</th><th>{tr("Montant", "Amount")}</th></tr></thead><tbody>{rows.map(item => <tr key={`${item.kind}-${item.id}`}><td><strong>{labels[item.kind] || item.kind}</strong><small>{item.title}</small></td><td>{dateLabel(item.date, en)}</td><td>{item.provider}<small>{item.source === "provider" ? tr("Fournisseur", "Provider") : item.source === "import" ? tr("Import CSV", "CSV import") : tr("Événement serveur", "Server event")}</small></td><td><span className={`ss-br__pill ${item.linked ? "is-good" : ""}`}>{item.linked ? item.attribution === "manual_import" ? tr("Origine déclarée", "Declared origin") : tr("Lien observé", "Observed link") : tr("Inconnue", "Unknown")}</span></td><td>{formatBusinessMoney(item.amount, item.currency, en)}<small>{item.status === "paid" ? item.source === "import" ? tr("Déclaré à l’import", "Recorded on import") : tr("Confirmé par la source", "Confirmed by source") : item.status}</small></td></tr>)}</tbody></table></div>}</section>;
}

function BusinessEntryForm({ kind, data, english: en, posts, channels, publication, experiment, onClose, onSaved }: { publication?: BusinessPublication; experiment?: BusinessExperiment; kind: Exclude<Dialog, null>; data: BusinessDashboard; english: boolean; posts: ReturnType<typeof useStudio>["posts"]; channels: ReturnType<typeof useStudio>["channels"]; onClose: () => void; onSaved: () => Promise<void> }) {
  const tr: Translate = (fr, english) => en ? english : fr;
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [selectedPost, setSelectedPost] = useState(publication?.contentId || "");
  const [lifecycle, setLifecycle] = useState<"planned" | "published">(publication ? "published" : "planned");
  const post = posts.find(item => item.id === selectedPost);
  const titles = { publication: tr("Suivre une publication", "Track a publication"), link: tr("Créer un lien traçable", "Create a trackable link"), cost: tr("Renseigner un coût", "Record a cost"), event: tr("Ajouter un signal déclaré", "Add a manually recorded signal"), experiment: tr("Préparer une expérience", "Plan an experiment") };
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); setBusy(true); setError(""); const values = new FormData(event.currentTarget); const text = (name: string) => String(values.get(name) || "").trim(); const optional = (name: string) => text(name) || undefined;
    try {
      let path: string; let payload: unknown;
      if (kind === "publication") { path = "/publications"; payload = { id: publication?.id, lifecycle, contentId: selectedPost || undefined, channelId: optional("channelId"), externalId: post?.tiktokId || publication?.externalId || undefined, url: optional("url"), title: text("title"), publishedAt: new Date(text("publishedAt")).toISOString(), format: text("format"), hook: optional("hook"), cta: optional("cta"), destinationUrl: optional("destinationUrl") }; }
      else if (kind === "link") { path = "/links"; payload = { label: text("label"), destinationUrl: text("destinationUrl"), publicationId: optional("publicationId"), campaign: optional("campaign") }; }
      else if (kind === "cost") { path = "/costs"; payload = { publicationId: optional("publicationId"), name: text("name"), amountMinor: moneyToMinor(text("amount"), text("currency")), currency: text("currency"), category: text("category"), incurredAt: new Date(text("incurredAt")).toISOString() }; }
      else if (kind === "event") { path = "/events"; payload = { kind: text("kind"), occurredAt: new Date(text("occurredAt")).toISOString(), publicationId: optional("publicationId"), value: optional("value") }; }
      else { path = "/experiments"; payload = { id: experiment?.id, name: text("name"), hypothesis: text("hypothesis"), metric: text("metric"), publicationIds: values.getAll("publicationIds").map(String), status: text("status") }; }
      await businessRequest(path, payload); await onSaved();
    } catch (failure) { setError(businessError(failure, en)); } finally { setBusy(false); }
  }
  const publicationSelect = <BusinessField label={tr("Publication (facultatif)", "Publication (optional)")}><select name="publicationId" defaultValue={publication?.id || ""}><option value="">{tr("Aucune publication", "No publication")}</option>{data.publications.map(item => <option key={item.id} value={item.id}>{item.title}</option>)}</select></BusinessField>;
  return <BusinessModal title={titles[kind]} onClose={() => { if (!busy) onClose(); }} english={en} wide={kind === "publication"}><form className="ss-br__form" onSubmit={event => void submit(event)}>{error && <div className="ss-br__notice is-error" role="alert">{error}</div>}
    {kind === "publication" && <><BusinessField label={tr("État du contenu", "Content stage")} hint={tr("Prépare le contenu et son lien avant publication pour observer une période complète.", "Prepare content and its link before publishing to observe a complete period.")}><select value={lifecycle} onChange={event => setLifecycle(event.target.value as "planned" | "published")}><option value="planned">{tr("Préparer un contenu", "Prepare content")}</option><option value="published">{tr("Déjà publié", "Already published")}</option></select></BusinessField>{!publication && <BusinessField label={tr("Depuis le calendrier", "From the calendar")}><select value={selectedPost} onChange={event => { setSelectedPost(event.target.value); const selected = posts.find(item => item.id === event.target.value); if (selected) setLifecycle(selected.status === "published" ? "published" : "planned"); }}><option value="">{tr("Saisir un contenu", "Enter content")}</option>{posts.filter(item => !data.publications.some(pub => pub.contentId === item.id)).map(item => <option value={item.id} key={item.id}>{item.body.slice(0, 90) || item.id}</option>)}</select></BusinessField>}<div key={selectedPost}><BusinessField label={tr("Titre du contenu", "Content title")}><input name="title" required maxLength={300} defaultValue={publication?.title || post?.body.slice(0, 160) || ""} /></BusinessField><div className="ss-br__form-grid"><BusinessField label={tr("Compte de publication", "Publishing account")}><select name="channelId" defaultValue={publication?.channelId || post?.publishChannelId || post?.channelIds[0] || ""}><option value="">{tr("Non renseigné", "Unspecified")}</option>{channels.filter(item => item.connected && !item.tracked).map(item => <option value={item.id} key={item.id}>@{item.handle}</option>)}</select></BusinessField><BusinessField label={lifecycle === "planned" ? tr("Date prévue", "Planned date") : tr("Date réelle de publication", "Actual publication date")}><input name="publishedAt" required type="datetime-local" max={lifecycle === "published" ? localInputDate() : undefined} defaultValue={localInputDate(publication ? publication.lifecycle === "planned" ? new Date() : new Date(publication.publishedAt) : post?.publishedAt ? new Date(post.publishedAt) : new Date())} /></BusinessField></div><BusinessField label={tr("URL du post (facultatif)", "Post URL (optional)")}><input name="url" type="url" defaultValue={publication?.url || post?.tiktokUrl || ""} placeholder="https://www.tiktok.com/@…" /></BusinessField><div className="ss-br__form-grid"><BusinessField label={tr("Format", "Format")}><input name="format" required maxLength={80} defaultValue={publication?.format || ""} placeholder={tr("Tutoriel, liste, avant/après…", "Tutorial, list, before/after…")} /></BusinessField><BusinessField label={tr("Appel à l'action", "Call to action")}><input name="cta" maxLength={300} defaultValue={publication?.cta || ""} placeholder={tr("Essayer l'app", "Try the app")} /></BusinessField></div><BusinessField label={tr("Accroche", "Hook")}><input name="hook" maxLength={500} defaultValue={publication?.hook || ""} /></BusinessField><BusinessField label={tr("Destination commerciale (facultatif)", "Business destination (optional)")}><input name="destinationUrl" type="url" placeholder="https://…" defaultValue={publication?.destinationUrl || ""} /></BusinessField></div><p className="ss-br__caption">{tr("Aucune statistique sociale n'est créée à la main. Le suivi commence avec les données réellement collectées.", "Social statistics are never created manually. Tracking starts with data actually collected.")}</p></>}
    {kind === "link" && <><BusinessField label={tr("Nom du lien", "Link name")}><input name="label" required maxLength={160} defaultValue={publication?.title.slice(0, 160) || ""} placeholder={tr("Essai gratuit — tutoriel", "Free trial — tutorial")} /></BusinessField><BusinessField label={tr("URL de destination", "Destination URL")}><input name="destinationUrl" required type="url" defaultValue={publication?.destinationUrl || data.settings.siteUrl || ""} placeholder="https://…" /></BusinessField>{publicationSelect}<BusinessField label={tr("Campagne (facultatif)", "Campaign (optional)")}><input name="campaign" maxLength={160} /></BusinessField></>}
    {kind === "cost" && <><BusinessField label={tr("Nom de la dépense", "Expense name")}><input name="name" required maxLength={160} /></BusinessField><div className="ss-br__form-grid"><BusinessField label={tr("Montant", "Amount")}><input name="amount" type="number" min="0" step="any" required inputMode="decimal" /></BusinessField><BusinessField label={tr("Devise", "Currency")}><select name="currency" defaultValue={data.currency}>{currencyOptions.map(item => <option key={item}>{item}</option>)}</select></BusinessField></div>{publicationSelect}<div className="ss-br__form-grid"><BusinessField label={tr("Catégorie", "Category")}><select name="category">{([['production', 'Production', 'Production'], ['creator', 'Créateur', 'Creator'], ['tools', 'Outils', 'Tools'], ['cogs', 'Coût produit', 'Product cost'], ['shipping', 'Livraison', 'Shipping'], ['ads', 'Publicité', 'Advertising'], ['other', 'Autre', 'Other']] as const).map(([value, fr, eng]) => <option key={value} value={value}>{tr(fr, eng)}</option>)}</select></BusinessField><BusinessField label={tr("Date", "Date")}><input name="incurredAt" type="datetime-local" required defaultValue={localInputDate()} /></BusinessField></div></>}
    {kind === "event" && <><p className="ss-br__caption" style={{ marginBottom: 18 }}>{tr("Cet événement sera marqué « déclaré manuellement ». Ce formulaire ne peut pas créer une vente confirmée.", "This event will be marked as manually recorded. This form cannot create a confirmed sale.")}</p><div className="ss-br__form-grid"><BusinessField label={tr("Signal", "Signal")}><select name="kind"><option value="lead">Lead</option><option value="signup">{tr("Inscription", "Signup")}</option><option value="activation">Activation</option><option value="trial">{tr("Essai", "Trial")}</option><option value="survey">{tr("Réponse d'enquête", "Survey response")}</option></select></BusinessField><BusinessField label={tr("Date", "Date")}><input name="occurredAt" type="datetime-local" required defaultValue={localInputDate()} /></BusinessField></div>{publicationSelect}<BusinessField label={tr("Note ou réponse (facultatif)", "Note or response (optional)")}><textarea name="value" maxLength={500} placeholder={tr("Sans donnée personnelle du client", "Do not include customer personal data")} /></BusinessField></>}
    {kind === "experiment" && <><BusinessField label={tr("Nom de l'expérience", "Experiment name")}><input name="name" required maxLength={160} defaultValue={experiment?.name || ""} /></BusinessField><BusinessField label={tr("Hypothèse à explorer", "Hypothesis to explore")}><textarea name="hypothesis" required maxLength={1000} defaultValue={experiment?.hypothesis || ""} placeholder={tr("Une démonstration concrète pourrait amener davantage d'inscriptions…", "A concrete demonstration could bring more signups…")} /></BusinessField><div className="ss-br__form-grid"><BusinessField label={tr("Métrique observée", "Observed metric")}><select name="metric" defaultValue={experiment?.metric || "signups"}><option value="signups">{tr("Inscriptions", "Signups")}</option><option value="visits">{tr("Visites", "Visits")}</option><option value="buyers">{tr("Acheteurs", "Buyers")}</option><option value="revenue_per_post">{tr("Revenu par post", "Revenue per post")}</option></select></BusinessField><BusinessField label={tr("État", "Status")}><select name="status" defaultValue={experiment?.status || "planned"}><option value="planned">{tr("Préparée", "Planned")}</option><option value="running">{tr("En cours", "Running")}</option><option value="completed">{tr("Terminée", "Completed")}</option></select></BusinessField></div><BusinessField label={tr("Publications à comparer", "Publications to compare")} hint={tr("Sélection multiple. Tu peux aussi préparer une expérience sans publication.", "Multiple selection. You can also plan an experiment before adding publications.")}><select name="publicationIds" defaultValue={experiment?.publicationIds || []} multiple size={Math.min(5, Math.max(2, data.publications.length))}>{data.publications.map(item => <option value={item.id} key={item.id}>{item.title}</option>)}</select></BusinessField></>}
    <div className="ss-br__modal-footer"><button className="ss-br__button" type="button" disabled={busy} onClick={onClose}>{tr("Annuler", "Cancel")}</button><button className="ss-br__primary" type="submit" disabled={busy}>{busy ? tr("Enregistrement…", "Saving…") : tr("Enregistrer", "Save")}</button></div>
  </form></BusinessModal>;
}

function BusinessSimulator({ currency, english: en }: { currency: string; english: boolean }) {
  const tr: Translate = (fr, eng) => en ? eng : fr;
  const [values, setValues] = useState({ views: "", clickRate: "", purchaseRate: "", basket: "", costs: "" });
  const ready = Object.values(values).every(value => value !== "" && Number.isFinite(Number(value)) && Number(value) >= 0) && Number(values.clickRate) <= 100 && Number(values.purchaseRate) <= 100;
  const visits = ready ? Number(values.views) * Number(values.clickRate) / 100 : null;
  const buyers = visits == null ? null : visits * Number(values.purchaseRate) / 100;
  const revenue = buyers == null ? null : buyers * moneyToMinor(values.basket, currency);
  const afterCosts = revenue == null ? null : revenue - moneyToMinor(values.costs, currency);
  return <section className="ss-br__panel"><PanelTitle title={tr("Et si…", "What if…")} detail={tr("Un scénario calculé à partir de tes hypothèses. Aucune prévision IA et aucune modification de tes résultats.", "A scenario calculated from your assumptions. No AI forecast and no changes to your results.")} /><div className="ss-br__grid ss-br__grid--equal" style={{ margin: "0 24px 24px" }}><div>{([['views', tr('Vues supposées', 'Assumed views'), undefined], ['clickRate', tr('Part visitant le site (%)', 'Share visiting the site (%)'), 100], ['purchaseRate', tr('Part des visites converties (%)', 'Share of visits converting (%)'), 100], ['basket', tr(`Panier moyen supposé (${currency})`, `Assumed average order (${currency})`), undefined], ['costs', tr(`Coûts supposés (${currency})`, `Assumed costs (${currency})`), undefined]] as const).map(([key, label, max]) => <BusinessField label={label} key={key}><input type="number" min="0" max={max} step="any" value={values[key]} placeholder="—" onChange={event => setValues(current => ({ ...current, [key]: event.target.value }))} /></BusinessField>)}</div><div><span className="ss-br__pill">{tr("Hypothèses personnelles", "Your assumptions")}</span><div style={{ marginTop: 30 }}><Metric label={tr("Revenu du scénario", "Scenario revenue")} value={formatBusinessMoney(revenue, currency, en)} detail={tr("Avant taxes, remboursements et frais", "Before tax, refunds and fees")} /></div><div className="ss-br__key-value"><span>{tr("Visites théoriques", "Theoretical visits")}</span><b>{visits == null ? "—" : Math.round(visits).toLocaleString()}</b></div><div className="ss-br__key-value"><span>{tr("Achats théoriques", "Theoretical purchases")}</span><b>{buyers == null ? "—" : buyers.toLocaleString(en ? "en-GB" : "fr-FR", { minimumFractionDigits: 1, maximumFractionDigits: 1 })}</b></div><div className="ss-br__key-value"><span>{tr("Après coûts saisis", "After entered costs")}</span><b>{formatBusinessMoney(afterCosts, currency, en)}</b></div><p className="ss-br__caption">{tr("Renseigne chaque hypothèse pour calculer le scénario. Ces montants ne sont ni des ventes observées ni une promesse de résultat.", "Enter each assumption to calculate the scenario. These amounts are neither observed sales nor a promise of results.")}</p></div></div></section>;
}

function BusinessSettingsPanel({ data, english: en, origin, reload }: { data: BusinessDashboard; english: boolean; origin: string; reload: () => Promise<void> }) {
  const tr: Translate = (fr, english) => en ? english : fr;
  const [busy, setBusy] = useState("");
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [keyResult, setKeyResult] = useState<{ key: string; prefix: string; endpoint: string; scriptUrl?: string } | null>(null);
  const [keyConfirm, setKeyConfirm] = useState(false);
  const [csv, setCsv] = useState("");
  const [preview, setPreview] = useState<ImportPreview | null>(null);
  const [previewCsv, setPreviewCsv] = useState("");
  async function settings(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const form = new FormData(event.currentTarget); setBusy("settings"); setError("");
    try { await businessRequest("/settings", { currency: form.get("currency"), attributionWindowDays: Number(form.get("window")), horizonDays: Number(form.get("horizon")), siteUrl: String(form.get("siteUrl") || "").trim() || undefined, bioSlug: String(form.get("bioSlug") || "").trim() || undefined, bioEnabled: form.get("bioEnabled") === "on", costsComplete: form.get("costsComplete") === "on" }, "PATCH"); setNotice(tr("Réglages enregistrés.", "Settings saved.")); await reload(); }
    catch (failure) { setError(businessError(failure, en)); } finally { setBusy(""); }
  }
  async function createKey() {
    setBusy("key"); setError("");
    try { setKeyResult(await businessRequest("/tracking/keys", {})); setKeyConfirm(false); await reload(); }
    catch (failure) { setError(businessError(failure, en)); } finally { setBusy(""); }
  }
  async function importCsv(dryRun: boolean) {
    setBusy("import"); setError("");
    try { const response = await businessRequest<ImportPreview>("/import", { provider: "manual", csv, dryRun }); setPreview(response); setPreviewCsv(csv); if (!dryRun) { setNotice(tr(`${response.imported || 0} transactions importées, ${response.skipped || 0} ignorées.`, `${response.imported || 0} transactions imported, ${response.skipped || 0} skipped.`)); setPreview(null); setPreviewCsv(""); await reload(); } }
    catch (failure) { setError(businessError(failure, en)); } finally { setBusy(""); }
  }
  const codeUrl = (value?: string) => value?.startsWith("/") ? `${origin}${value}` : value || "";
  return <>{error && <div className="ss-br__notice is-error" role="alert">{error}</div>}{notice && <div className="ss-br__notice is-success" role="status">{notice}</div>}<div className="ss-br__grid ss-br__grid--equal"><section className="ss-br__panel"><PanelTitle title={tr("Règles de mesure", "Measurement settings")} detail={tr("Des définitions explicites, appliquées au projet actif.", "Explicit definitions, applied to the current project.")} /><form className="ss-br__form" onSubmit={event => void settings(event)} key={data.settings.updatedAt}><div className="ss-br__form-grid"><BusinessField label={tr("Devise par défaut", "Default currency")}><select name="currency" defaultValue={data.settings.currency}>{currencyOptions.map(value => <option key={value}>{value}</option>)}</select></BusinessField><BusinessField label={tr("Fenêtre d'attribution (jours)", "Attribution window (days)")}><input name="window" type="number" min="1" max="90" required defaultValue={data.settings.attributionWindowDays} /></BusinessField></div><BusinessField label={tr("Horizon de comparaison (jours)", "Comparison horizon (days)")}><select name="horizon" defaultValue={data.settings.horizonDays}>{[7, 14, 30, 60, 90].map(value => <option value={value} key={value}>{value}</option>)}</select></BusinessField><BusinessField label={tr("Site de ton activité", "Your business website")}><input type="url" name="siteUrl" placeholder="https://…" defaultValue={data.settings.siteUrl || ""} /></BusinessField><BusinessField label={tr("Adresse de la page bio", "Bio page address")} hint={`${origin}/b/…`}><input name="bioSlug" minLength={3} maxLength={60} pattern="[a-z0-9]+(?:-[a-z0-9]+)*" placeholder="mon-business" defaultValue={data.settings.bioSlug || ""} /></BusinessField><label className="ss-br__check"><input name="bioEnabled" type="checkbox" defaultChecked={data.settings.bioEnabled} /><span>{tr("Rendre la page bio publique avec les liens actifs de ce projet.", "Make the bio page public with active links from this project.")}</span></label><label className="ss-br__check"><input name="costsComplete" type="checkbox" defaultChecked={data.settings.costsComplete} /><span>{tr("J'ai renseigné tous les coûts nécessaires à la contribution des contenus.", "I have recorded all costs needed for content contribution calculations.")}</span></label><button className="ss-br__primary" disabled={!!busy}>{busy === "settings" ? tr("Enregistrement…", "Saving…") : tr("Enregistrer les réglages", "Save settings")}</button></form></section>
      <section className="ss-br__panel"><PanelTitle title={tr("Installer le suivi", "Install tracking")} detail={tr("La clé et la réception d'événements sont deux étapes distinctes.", "The key and event delivery are two separate steps.")} /><div className="ss-br__panel-body"><div className="ss-br__key-value"><span>{tr("Clé du projet", "Project key")}</span><span className={`ss-br__pill ${data.capabilities.trackingKeyConfigured ? "is-good" : "is-warn"}`}>{data.capabilities.trackingKeyConfigured ? tr("Créée", "Created") : tr("À créer", "Not created")}</span></div><div className="ss-br__key-value"><span>{tr("Suivi observé", "Observed tracking")}</span><span className={`ss-br__pill ${data.capabilities.trackingObserved ? "is-good" : "is-warn"}`}>{data.capabilities.trackingObserved ? tr("Événements reçus", "Events received") : tr("À vérifier", "To verify")}</span></div><ol className="ss-br__progress-list"><li><span>1</span><div><strong>{tr("Crée une clé serveur", "Create a server key")}</strong><p>{tr("Elle sera affichée une seule fois. Garde-la dans les secrets de ton serveur.", "It is shown once. Keep it in your server secrets.")}</p></div></li><li><span>2</span><div><strong>{tr("Conserve le clic pendant le parcours", "Keep the click through the journey")}</strong><p>{tr("Le lien traçable transmet l'identifiant qui doit accompagner l'inscription puis le client payeur.", "The tracked link passes an identifier that must accompany signup and the paying customer.")}</p></div></li><li><span>3</span><div><strong>{tr("Vérifie un événement réel", "Verify a real event")}</strong><p>{tr("La carte de santé change uniquement après réception, pas après la copie du code.", "Health changes only after receipt, not after copying code.")}</p></div></li></ol><button className="ss-br__button lg lg--lens" disabled={!!busy} onClick={() => data.capabilities.trackingKeyConfigured ? setKeyConfirm(true) : void createKey()}>{busy === "key" ? tr("Création…", "Creating…") : data.capabilities.trackingKeyConfigured ? tr("Remplacer la clé", "Replace key") : tr("Créer la clé de suivi", "Create tracking key")}</button>{keyResult && <div className="ss-br__import-preview"><p><strong>{tr("Copie ta clé maintenant", "Copy your key now")}</strong></p><p className="ss-br__caption">{tr("Elle ne sera plus visible après avoir quitté cette page. Ne l'intègre pas au JavaScript public.", "It will not be visible after leaving this page. Do not include it in public JavaScript.")}</p><pre className="ss-br__code">{keyResult.key}</pre><CopyButton value={keyResult.key} english={en} /><p className="ss-br__caption">{tr("Endpoint serveur", "Server endpoint")}</p><pre className="ss-br__code">{codeUrl(keyResult.endpoint)}</pre>{keyResult.scriptUrl && <><p className="ss-br__caption">{tr("Script public, sans clé secrète", "Public script, without the secret key")}</p><pre className="ss-br__code">{`<script defer src="${codeUrl(keyResult.scriptUrl)}"></script>`}</pre><CopyButton value={`<script defer src="${codeUrl(keyResult.scriptUrl)}"></script>`} english={en} /></>}</div>}<details style={{ marginTop: 20 }}><summary>{tr("Code d’installation et contrat des événements", "Installation code and event contract")}</summary><p className="ss-br__caption">{tr("Sur la page d’arrivée : le script lit uniquement le clic présent dans l’URL. Sans stockage ni appel réseau par défaut.", "On the landing page: the script only reads the click in the URL. No storage or network calls by default.")}</p><pre className="ss-br__code">{`<script defer src="${origin}/scrollshow-tracking.js"></script>
// Après chargement du script :
const { clickId } = window.ScrollShowAttribution.get();
// Transmets clickId à ton serveur avec l'inscription.
// Conservation facultative, uniquement après consentement :
window.ScrollShowAttribution.remember({ consent: true });`}</pre><p className="ss-br__caption">{tr("Sur ton serveur après une inscription réelle, associe le clic à l’identifiant client utilisé par le paiement et à la connexion business correspondante. Un eventId stable empêche les doublons.", "On your server after a real signup, associate the click with the customer ID used for payment and the corresponding business connection. A stable eventId prevents duplicates.")}</p><pre className="ss-br__code">{`await fetch("${origin}/api/business/ingest", {
  method: "POST",
  headers: {
    "Content-Type": "application/json",
    Authorization: "Bearer " + process.env.SCROLLSHOW_TRACKING_KEY
  },
  body: JSON.stringify({
    eventId: "signup-UNIQUE",
    kind: "signup",
    clickId,
    customerId: "CUSTOMER_ID",
    connectionId: "BUSINESS_CONNECTION_ID"
  })
});`}</pre>{data.connections.filter(item => item.status !== "disconnected").map(item => <p className="ss-br__caption" key={item.id}>{item.name} : <code>{item.id}</code></p>)}<p className="ss-br__caption">{tr("N’envoie pas de ventes à cet endpoint : les paiements sont confirmés par le webhook du fournisseur. Événements acceptés : visit, signup, activation, lead, trial, survey. La conservation consentie du clic dure 7 jours.", "Do not send sales to this endpoint: payments are confirmed by provider webhooks. Accepted events: visit, signup, activation, lead, trial, survey. Consented click storage lasts 7 days.")}</p></details></div></section></div>
    <section className="ss-br__panel"><PanelTitle title={tr("Importer un historique vérifiable", "Import reviewable history")} detail={tr("Prévisualise les lignes avant de les ajouter. L'import ne reconstruit pas l'origine des ventes inconnues.", "Preview rows before adding them. Import does not reconstruct unknown sales origins.")} action={<a className="ss-br__button lg lg--lens" href="/api/business/export?kind=transactions" download>{tr("Exporter le journal", "Export ledger")}</a>} /><div className="ss-br__panel-body"><p className="ss-br__caption">{tr("Colonnes CSV : les 4 premières sont obligatoires. Montants entiers en centimes (EUR/USD), taxe vide = inconnue. refund_of référence une vente de cet import ou d’un import précédent.", "CSV columns: the first 4 are required. Integer amounts in cents (EUR/USD), empty tax = unknown. refund_of references a sale from this or a previous import.")}</p><pre className="ss-br__code">external_id,occurred_at,amount_minor,currency,tax_minor,kind,customer_ref,publication_id,refund_of</pre><BusinessField label={tr("Fichier CSV", "CSV file")}><input type="file" accept=".csv,text/csv" onChange={async event => { const file = event.target.files?.[0]; if (!file) return; if (file.size > 500_000) { setError(tr("Le fichier doit faire moins de 500 Ko.", "The file must be smaller than 500 KB.")); return; } setCsv(await file.text()); setPreview(null); }} /></BusinessField><BusinessField label={tr("Ou coller le CSV", "Or paste CSV")} hint={tr("Chaque transaction doit avoir un identifiant stable, une date, un montant et une devise. La validation indique les colonnes ou valeurs à corriger.", "Each transaction needs a stable ID, date, amount and currency. Validation identifies columns or values to correct.")}><textarea rows={7} value={csv} onChange={event => { setCsv(event.target.value); setPreview(null); }} spellCheck={false} /></BusinessField><div className="ss-br__actions"><button className="ss-br__button lg lg--lens" disabled={!!busy || !csv.trim()} onClick={() => void importCsv(true)}>{busy === "import" ? tr("Vérification…", "Checking…") : tr("Prévisualiser l'import", "Preview import")}</button><button className="ss-br__primary" disabled={!!busy || !preview?.valid || previewCsv !== csv} onClick={() => void importCsv(false)}>{tr("Confirmer l'import", "Confirm import")}</button></div>{preview && <div className="ss-br__import-preview"><strong>{preview.valid ? tr(`${preview.rows.length} lignes valides`, `${preview.rows.length} valid rows`) : tr("Corrige les erreurs avant l'import", "Correct errors before importing")}</strong>{preview.errors.length > 0 && <ul>{preview.errors.slice(0, 20).map((item, index) => <li key={index}>{item.row ? `${tr("Ligne", "Row")} ${item.row} : ` : ""}{businessError(new Error(item.message), en)}</li>)}</ul>}{preview.rows.length > 0 && <div className="ss-br__table-scroll"><table><thead><tr>{Object.keys(preview.rows[0]).filter(key => !/customer|email|secret|key/i.test(key)).slice(0, 6).map(key => <th key={key}>{key}</th>)}</tr></thead><tbody>{preview.rows.slice(0, 8).map((row, index) => <tr key={index}>{Object.keys(preview.rows[0]).filter(key => !/customer|email|secret|key/i.test(key)).slice(0, 6).map(key => <td key={key}>{String(row[key] ?? "—")}</td>)}</tr>)}</tbody></table></div>}<p className="ss-br__caption">{tr("Source enregistrée : import manuel. Aucune ligne n'est considérée comme vérifiée par un prestataire de paiement.", "Recorded source: manual import. No row is treated as verified by a payment provider.")}</p></div>}</div></section>
    {keyConfirm && <BusinessModal title={tr("Remplacer la clé de suivi ?", "Replace the tracking key?")} english={en} onClose={() => setKeyConfirm(false)}><div className="ss-br__modal-content"><p>{tr("Le suivi installé devra utiliser la nouvelle clé. Copie-la puis remplace le secret de ton serveur pour continuer à recevoir les événements.", "Installed tracking will need the new key. Copy it, then replace your server secret to keep receiving events.")}</p><div className="ss-br__modal-footer"><button className="ss-br__button" onClick={() => setKeyConfirm(false)}>{tr("Annuler", "Cancel")}</button><button className="ss-br__primary" disabled={!!busy} onClick={() => void createKey()}>{tr("Remplacer", "Replace")}</button></div></div></BusinessModal>}
  </>;
}
